import {createClient} from 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm';
const cfg=window.GIFT_CONFIG||{};const configured=cfg.url?.startsWith('https://')&& !cfg.anonKey?.startsWith('PASTE_');
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
let sb,user,family,members=[],wishes=[],dna=[],battles=[],votes=[],vault=[],mine=new Set(),reserved=new Set(),tab='home',selectedMember=null;
// In-app navigation history, scoped to the current login and circle.
const pageHistory=[];let navigationEpoch=0;
function updateBack(){ $('appBack').hidden=!family||!user||recovering||pageHistory.length===0; }
function resetNavigation(){if($('accountDialog').open)$('accountDialog').close();$('accountOpen').hidden=true;$('identity').textContent='';$('circleHeader').hidden=true;pageHistory.length=0;navigationEpoch++;tab='home';selectedMember=null;$('appBack').hidden=true;}
function navigate(next,person=null){if(!family||!user)return;if(next===tab&&(next!=='person'||person===selectedMember))return;pageHistory.push({tab,person:selectedMember,y:window.scrollY});if(pageHistory.length>100)pageHistory.shift();navigationEpoch++;tab=next;selectedMember=person;render();window.scrollTo(0,0);}
function goBack(){if(!family||!user||!pageHistory.length)return;const prev=pageHistory.pop(),epoch=++navigationEpoch;tab=prev.tab;selectedMember=prev.person;render();const restore=()=>{if(epoch===navigationEpoch&&family&&user)window.scrollTo(0,prev.y)};requestAnimationFrame(restore);setTimeout(()=>{if(epoch===navigationEpoch&&window.scrollY<prev.y&&document.documentElement.scrollHeight-window.innerHeight>window.scrollY)restore()},350);}
$('appBack').onclick=goBack;
$('accountOpen').onclick=()=>{if(!user||recovering)return;$('identity').textContent=user.email||'';$('accountCircleActions').hidden=!family||!me();$('accountDialog').showModal()};
$('accountClose').onclick=()=>$('accountDialog').close();
document.querySelectorAll('[data-account-tab]').forEach(b=>b.onclick=()=>{if(!user||!family||recovering)return;$('accountDialog').close();navigate(b.dataset.accountTab)});
function msg(s){$('status').textContent=s||''}function fail(e){msg(e?.message||String(e))}function card(s){return `<section class="card">${s}</section>`}function me(){return members.find(m=>m.user_id===user.id)}function name(id){return members.find(m=>m.user_id===id)?.display_name||'Member'}
async function run(fn){try{msg('');await fn()}catch(e){fail(e)}}
const recoveryURL=new URL(location.href);
const recoveryRequested=recoveryURL.searchParams.get('recovery')==='1'||new URLSearchParams(location.hash.slice(1)).get('type')==='recovery';
let recovering=recoveryRequested,recoveryReady=false;
function cleanRecoveryURL(){const u=new URL(location.href);u.searchParams.delete('recovery');u.searchParams.delete('code');u.hash='';history.replaceState(null,'',u.href)}
function showRecovery(){resetNavigation();recovering=true;$('auth').classList.add('hidden');$('main').classList.add('hidden');$('recovery').classList.remove('hidden');$('savePassword').disabled=!recoveryReady;family=null;}
if(!configured){$('auth').innerHTML='<h2>⚙️ Setup required</h2><p>Configure <code>config.js</code> with your Supabase URL and publishable key, then upload this project to GitHub Pages. Follow README.md.</p>'}else{
 sb=createClient(cfg.url,cfg.anonKey);$('login').onclick=()=>run(async()=>{let {error}=await sb.auth.signInWithPassword({email:$('email').value,password:$('password').value});if(error)throw error});
 $('signup').onclick=()=>run(async()=>{let {error}=await sb.auth.signUp({email:$('email').value,password:$('password').value});if(error)throw error;msg('Account created. Check email for a confirmation link if required.')});
 $('reset').onclick=()=>run(async()=>{if(!$('email').value)throw Error('Enter your email first');let {error}=await sb.auth.resetPasswordForEmail($('email').value,{redirectTo:location.origin+location.pathname+'?recovery=1'});if(error)throw error;msg('Password reset email requested.')});
 $('logout').onclick=()=>run(async()=>{$('accountDialog').close();let {error}=await sb.auth.signOut();if(error)throw error});
 if(recovering){showRecovery();msg('Verifying your password reset link…')}
 $('recoveryForm').onsubmit=e=>{e.preventDefault();run(async()=>{if(!recoveryReady)throw Error('Request a fresh password reset link.');const password=$('newPassword').value;if(password.length<6)throw Error('Use at least 6 characters.');if(password!==$('confirmPassword').value)throw Error('Passwords do not match.');$('savePassword').disabled=true;try{const {error}=await sb.auth.updateUser({password});if(error)throw error;const result=await sb.auth.signOut();if(result.error)throw result.error;recovering=false;recoveryReady=false;cleanRecoveryURL();$('recoveryForm').reset();$('recovery').classList.add('hidden');user=null;await boot();msg('Password updated. Sign in with your new password.')}finally{$('savePassword').disabled=!recoveryReady}})};
 $('cancelRecovery').onclick=()=>run(async()=>{const {error}=await sb.auth.signOut();if(error)throw error;recovering=false;recoveryReady=false;cleanRecoveryURL();$('recoveryForm').reset();$('recovery').classList.add('hidden');user=null;await boot();msg('Request a new reset link if needed.')});
 sb.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'){recovering=true;recoveryReady=!!session;showRecovery()}setTimeout(()=>{user=session?.user||null;if(recovering){showRecovery();if(event==='PASSWORD_RECOVERY')msg('Enter your new password.');else if(event==='INITIAL_SESSION'&&!recoveryReady)msg('If your reset form remains disabled, request a fresh reset email.');return}if(event==='SIGNED_OUT'&& !user){$('recovery').classList.add('hidden');$('auth').classList.remove('hidden');$('main').classList.add('hidden');$('app').innerHTML='';$('setup').innerHTML='';++bootSequence;family=null;resetNavigation();return}if(event!=='TOKEN_REFRESHED'&&!(event==='SIGNED_IN'&&family&&members.some(m=>m.user_id===user?.id)))run(boot)},0)});
}
async function query(table,cols='*',filter){let q=sb.from(table).select(cols);if(filter)q=q.eq('family_id',family.id);let {data,error}=await q;if(error)throw error;return data||[]}
let bootSequence=0;
function circleKey(){return 'gift-happens-circle:'+user.id}
function rememberedCircle(){try{return localStorage.getItem(circleKey())}catch{return null}}
function chooseCircle(id){try{localStorage.setItem(circleKey(),id)}catch{}const u=new URL(location.href);u.searchParams.set('circle',id);location.assign(u.href)}
async function boot(){resetNavigation();const seq=++bootSequence;const uid=user?.id;family=null;members=[];$('auth').classList.toggle('hidden',!!user);$('main').classList.toggle('hidden',!user);$('app').innerHTML='';$('setup').innerHTML='';if(!user)return;$('identity').textContent=user.email;$('accountOpen').hidden=false;
const {data,error}=await sb.from('memberships').select('family_id,role,display_name').eq('user_id',uid);if(error)throw error;const f=await sb.from('families').select('id,name');if(f.error)throw f.error;if(seq!==bootSequence||user?.id!==uid)return;
const circles=(data||[]).map(m=>({...m,name:f.data.find(x=>x.id===m.family_id)?.name||'Gift Circle'})).sort((a,b)=>a.name.localeCompare(b.name)||a.family_id.localeCompare(b.family_id));const requested=new URL(location.href).searchParams.get('circle');const selected=circles.find(m=>m.family_id===requested)||circles.find(m=>m.family_id===rememberedCircle())||circles[0];
if(selected){const s=$('circleSelect');s.innerHTML=circles.map(m=>`<option value="${esc(m.family_id)}" ${m.family_id===selected.family_id?'selected':''}>${esc(m.name)}</option>`).join('');s.title=selected.name;s.onchange=()=>chooseCircle(s.value);$('circleHeader').hidden=false;try{localStorage.setItem(circleKey(),selected.family_id)}catch{};family={id:selected.family_id,role:selected.role,name:selected.name,displayName:selected.display_name};await refresh()}else{$('setup').innerHTML=circleForm('',true);wireCircleForm()}}
function circleForm(display='',first=false){return card(`<h3>🌎 Gift Circles</h3>${first?'<p>Join or create your first circle.</p>':''}<details ${first?'open':''}><summary>Create or join a circle</summary><label for="circleName">Your display name in the circle</label><input id="circleName" maxlength="40" value="${esc(display)}"><label for="circleInvite">Invitation code</label><input id="circleInvite"><button id="circleJoin">Join circle</button><hr><label for="circleNew">New circle name</label><input id="circleNew" maxlength="80"><button id="circleCreate" class="secondary">Create circle</button></details>`)}
function wireCircleForm(){if(!$('circleJoin'))return;const uid=user.id;async function addCircle(join){const display=$('circleName').value.trim(),value=$(join?'circleInvite':'circleNew').value.trim();if(!display||display.length>40||!value)throw Error('Enter a display name and '+(join?'invitation code':'circle name'));const buttons=[$('circleJoin'),$('circleCreate')];buttons.forEach(b=>b.disabled=true);try{const r=await sb.rpc(join?'join_family':'create_family',join?{invite_token:value,my_name:display}:{family_name:value,my_name:display});if(r.error)throw r.error;if(user?.id===uid)chooseCircle(r.data)}finally{buttons.forEach(b=>b.disabled=false)}}$('circleJoin').onclick=()=>run(()=>addCircle(true));$('circleCreate').onclick=()=>run(()=>addCircle(false))}
async function refresh(){if(!family)return;[members,wishes,dna,battles]=await Promise.all([query('memberships','*',true),query('wishes','*',true),query('gift_dna','*',true),query('battles','*',true)]);const voteResult=battles.length?await sb.from('votes').select('*').in('battle_id',battles.map(b=>b.id)):{data:[]};if(voteResult.error)throw voteResult.error;votes=voteResult.data||[];let r=await sb.rpc('my_reservations',{fid:family.id});if(r.error)throw r.error;mine=new Set((r.data||[]).map(x=>x.wish_id));r=await sb.rpc('reservation_status',{fid:family.id});if(r.error)throw r.error;reserved=new Set((r.data||[]).map(x=>x.wish_id));let vr=await sb.from('gift_vault').select('*').eq('family_id',family.id).eq('author_id',user.id).order('created_at',{ascending:false});if(vr.error)throw vr.error;vault=vr.data||[];const pr=await sb.from("gift_profiles").select("user_id,avatar").eq("family_id",family.id);if(pr.error)throw pr.error;profiles=pr.data||[];await loadWishPhotos();render()}
const core=['Something Under $25','Something I’d Never Buy Myself','Something I Need to Replace','Something for My Current Obsession','Something for My Cozy Era','Something to Level Up My Life','Something I’d Rather Do Than Own','Something I’m Embarrassed to Want','Something Nostalgic','Something That’s So Me','Something Worth Splurging On','Something You Choose for Me'];
function avatar(m){return profiles.find(p=>p.user_id===m.user_id)?.avatar|| ['🎧','✨','🎮','🎨','⚾','💜','🌟','🎁'][Array.from(m.user_id).reduce((a,c)=>a+c.charCodeAt(0),0)%8]}
let profiles=[];
function viewHome(){let own=wishes.filter(w=>w.owner_id===user.id);let categories=new Set(own.map(w=>w.category)).size;return `<section class="hero"><small>${esc(family.name)}</small><h2>Hey, ${esc(me()?.display_name||'friend')}! 👋</h2><p>Your family has excellent taste. Allegedly.</p><span class="hero-stat">🎁 ${own.length} wishes · ${categories} categories</span></section><div class="row"><h3>THE CREW</h3><button class="secondary" data-tab="family">Manage family</button></div><div class="crew">${members.map(m=>`<button class="member" data-person="${esc(m.user_id)}"><span>${avatar(m)}</span>${esc(m.display_name)}${m.user_id===user.id?' (you)':''}</button>`).join('')}${me()?.role==='admin'?'<button class="member invite" data-tab="family"><span>＋</span>Invite member</button>':''}</div>${card(`<h3>🎁 Your wishlist</h3><p class="muted">${categories} of ${core.length} categories explored</p><div class="progress"><div style="width:${Math.min(100,categories/core.length*100)}%"></div></div><button class="pink" data-tab="wishes">＋ Add a wish</button>`)}<div id="notificationPreview"></div><div id="personalDashboard"></div><div id="upcomingCelebrations"></div><h2>Explore Gift Happens</h2><div class="feature-grid">${[['wishes','🎁','Wishlists','Find their next favorite thing'],['vault','🔒','Secret Vault','Keep surprises secret'],['dna','🧬','Gift DNA','Your taste, decoded'],['chaos','🎲','Family Chaos','Weekly challenges and leaderboard'],['battle','🎲','Gift Battles','Let the family decide'],['santa','🎅','Secret Santa','Your secret holiday mission'],['intel','🕵️','Gift Intelligence','Clues, finds and secret questions'],['planner','🛍️','Gift Planning Pro','Private shopping and budgets'],['celebrations','🎉','Celebrations','Plan birthdays and special occasions'],['family','👥','Family','Manage your crew']].map(([id,e,l,d])=>`<button class="feature" data-tab="${id}"><span>${e}</span><strong>${l}</strong><small>${d}</small><b>Explore →</b></button>`).join('')}</div><section class="coming"><strong>🎲 Wildcard Wednesday</strong><p>Three answers. One weekly reveal.</p><button data-tab="chaos" class="pink">Play this week</button></section>`}
function viewPerson(){let m=members.find(x=>x.user_id===selectedMember);if(!m)return viewHome();let d=dna.find(x=>x.user_id===m.user_id)||{};return `<button class="secondary" data-tab="home">← The Crew</button><section class="hero"><h2>${avatar(m)} ${esc(m.display_name)}</h2><p>Gift profile</p></section>${card(`<h3>🧬 Gift DNA</h3><p><b>Favorites:</b> ${esc(d.favorites||'Not shared')}</p><p><b>Preferences:</b> ${esc(d.sizes||'Not shared')}</p><p><b>No-Go:</b> ${esc(d.no_go||'Not shared')}</p>`)}${card(`<h3>🎁 Wishlist</h3>${wishes.filter(w=>w.owner_id===m.user_id).map(w=>`<div class="item"><b>${esc(w.title)}</b><p class="muted">${esc(w.category)}</p>${shoppingDetails(w)}${/^https:\/\//i.test(w.link||'')?`<a href="${esc(w.link)}" target="_blank" rel="noopener noreferrer">View item</a>`:''}${m.user_id!==user.id?mine.has(w.id)?`<button data-unreserve="${w.id}">Reserved by you · Undo</button>`:reserved.has(w.id)?'<span class="pill">Already reserved</span>':`<button class="secondary" data-reserve="${w.id}">Reserve gift secretly</button>`:''}</div>`).join('')||'<p class="muted">No wishes yet.</p>'}<button data-tab="wishes">All wishlists</button>`)}`}
function render(){if(!family)return;updateBack();let t=[['home','🏠','Home'],['wishes','🎁','Wishes'],['arcade','🎲','Play'],['vault','🔒','Vault'],['family','☰','More']];$('app').innerHTML=(tab==='home'?viewHome():tab==='person'?viewPerson():tab==='wishes'?viewWishes():tab==='vault'?viewVault():tab==='dna'?viewDna():tab==='arcade'?viewArcade():tab==='arcadeDaily'?arcadeGame('🏆 Daily challenge','<div id="dailyGame"></div>'):['arcadeQuiz','arcadeMemory','arcadeGuess'].includes(tab)?viewArcadeGame():tab==='chaos'?viewChaos():tab==='battle'?viewBattles():tab==='santa'?viewSanta():tab==='intel'?viewIntel():tab==='celebrations'?viewCelebrations():tab==='planner'?viewPlanner():tab==='notifications'?viewNotifications():tab==='profile'?viewProfile():`<div class="row"><button data-tab="dna">🧬 Gift DNA</button><button data-tab="santa">🎅 Secret Santa</button><button data-tab="intel">🕵️ Gift Intelligence</button><button data-tab="celebrations">🎉 Celebrations</button><button data-tab="planner">🛍️ Gift Planning Pro</button></div>`+viewFamily())+`<nav class="tabs" aria-label="Main navigation">${t.map(([id,e,l])=>`<button data-tab="${id}" class="${tab===id||(id==='arcade'&&(['chaos','battle'].includes(tab)||tab.startsWith('arcade')))?'active':''}"><span>${e}</span>${l}</button>`).join('')}</nav>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{navigate(b.dataset.tab)});document.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>{navigate('person',b.dataset.person)});wire();wireCircleForm();if(tab==='santa')loadSanta();if(tab==='intel')loadIntel();if(tab==='chaos')loadChaos();if(tab==='celebrations')loadCelebrations();if(tab==='planner')loadPlanner();if(tab==='home'){loadUpcoming();loadDashboard();loadNotifications()}if(tab==='notifications')loadNotifications();if(tab==='profile')wireProfile();if(tab.startsWith('arcade'))wireArcade();if(tab==='arcade')loadCompetition();if(tab==='arcadeDaily')wireDaily()}
let wishFilter={person:'',category:'',search:'',sort:'default'};
function shoppingDetails(w){return `${(w.photo_path?photoURLs.get(w.photo_path):w.image_url)&&/^https:\/\//i.test(w.photo_path?photoURLs.get(w.photo_path):w.image_url)?`<img class="wish-photo" src="${esc(w.photo_path?photoURLs.get(w.photo_path):w.image_url)}" tabindex="0" role="button" title="Enlarge picture" alt="Product photo" loading="lazy" referrerpolicy="no-referrer">`:''}${w.estimated_price!=null?`<p><b>Estimated price: $${Number(w.estimated_price).toFixed(2)}</b></p>`:''}`}
function wishResults(){let rows=wishes.filter(w=>(!wishFilter.person||w.owner_id===wishFilter.person)&&(!wishFilter.category||w.category===wishFilter.category)&&w.title.toLowerCase().includes(wishFilter.search.toLowerCase()));if(wishFilter.sort!=='default')rows.sort((a,b)=>a.estimated_price==null?b.estimated_price==null?0:1:b.estimated_price==null?-1:(Number(a.estimated_price)-Number(b.estimated_price))*(wishFilter.sort==='high'?-1:1));return members.filter(m=>!wishFilter.person||m.user_id===wishFilter.person).map(m=>card(`<h3>${esc(m.display_name)} ${m.user_id===user.id?'(you)':''}</h3>${rows.filter(w=>w.owner_id===m.user_id).map(w=>`<div class="item"><strong>${esc(w.title)}</strong><div class="muted">${esc(w.category)}</div>${shoppingDetails(w)}${/^https:\/\//i.test(w.link||'')?`<a href="${esc(w.link)}" target="_blank" rel="noopener noreferrer">Shop item</a>`:''}<div>${w.owner_id===user.id?`<button class="secondary" data-edit-wish="${w.id}">Edit details</button><button class="secondary" data-delete="${w.id}">Remove</button>`:mine.has(w.id)?`<button data-unreserve="${w.id}">Reserved by you · Undo</button>`:reserved.has(w.id)?'<span class="pill">Already reserved</span>':`<button class="secondary" data-reserve="${w.id}">Reserve gift secretly</button>`}</div></div>`).join('')||'<p class="muted">No matching wishes.</p>'}`)).join('')}
function viewWishes(){return `<h2>🎁 Shopping Assistant</h2>${card(`<h3>Add a wish</h3><label>Gift idea</label><input id="wishTitle" maxlength="250"><label>Category</label><select id="wishCategory">${core.map(c=>`<option>${esc(c)}</option>`).join('')}</select><label>Product link (optional)</label><input id="wishLink" type="url"><label>Estimated price ($, optional)</label><input id="wishPrice" type="number" min="0" max="9999999999.99" step="0.01">${pictureFields("wish")}<button id="addWish" class="pink">Add wish</button>`)}${card(`<h3>Find a gift</h3><label>Family member</label><select id="filterPerson"><option value="">Everyone</option>${members.map(m=>`<option value="${esc(m.user_id)}" ${wishFilter.person===m.user_id?'selected':''}>${esc(m.display_name)}</option>`).join('')}</select><label>Category</label><select id="filterCategory"><option value="">All categories</option>${core.map(c=>`<option ${wishFilter.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select><label>Search</label><input id="filterSearch" value="${esc(wishFilter.search)}"><label>Sort within each person</label><select id="filterSort">${[['default','Default'],['low','Price low to high'],['high','Price high to low']].map(([v,l])=>`<option value="${v}" ${wishFilter.sort===v?'selected':''}>${l}</option>`).join('')}</select><button id="applyWishFilters">Apply filters</button><button id="clearWishFilters" class="secondary">Clear filters</button>`)}<div id="wishResults">${wishResults()}</div>`}
function wishPrice(v){if(v==='')return null;let n=Number(v);if(!Number.isFinite(n)||n<0||n>9999999999.99)throw Error('Enter a valid estimated price');return n}
function wishImage(v){v=v.trim();if(v&&(!/^https:\/\//i.test(v)||v.length>2048))throw Error('Use a direct HTTPS image URL');return v||null}
const photoURLs=new Map();
async function loadWishPhotos(){photoURLs.clear();const paths=[...new Set(wishes.map(w=>w.photo_path).filter(Boolean))];if(!paths.length)return;const {data,error}=await sb.storage.from('wish-pictures').createSignedUrls(paths,3600);if(!error)for(const x of data||[])if(x.signedUrl)photoURLs.set(x.path,x.signedUrl);}
function pictureFields(prefix,w={}){return `<label>Picture (optional)</label><select id="${prefix}Mode"><option value="none">No picture</option><option value="link" ${w.image_url&&!w.photo_path?'selected':''}>Use image link</option><option value="upload">Upload picture</option>${w.photo_path?'<option value="keep" selected>Keep existing picture</option>':''}</select><div id="${prefix}LinkBox"><label>Direct HTTPS image URL</label><input id="${prefix}Image" type="url" value="${esc(w.image_url||'')}"></div><div id="${prefix}FileBox"><label>Choose photo or screenshot</label><input id="${prefix}File" type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif"><p class="muted">Pictures are compressed before upload. HEIC depends on browser support.</p></div><img id="${prefix}Preview" class="wish-photo" alt="Picture preview" hidden>`}
function wirePicture(prefix,w={}){const mode=$(prefix+'Mode');if(!mode)return;const preview=$(prefix+'Preview');let sequence=0;const change=async()=>{const n=++sequence;$(prefix+'LinkBox').hidden=mode.value!=='link';$(prefix+'FileBox').hidden=mode.value!=='upload';preview.hidden=true;try{let src=mode.value==='keep'?photoURLs.get(w.photo_path):mode.value==='link'?wishImage($(prefix+'Image').value):mode.value==='upload'&&$(prefix+'File').files[0]?await readPreview($(prefix+'File').files[0]):null;if(n===sequence&&src){preview.src=src;preview.hidden=false}}catch(e){if(n===sequence)msg(e.message)}};mode.onchange=change;$(prefix+'File').onchange=change;$(prefix+'Image').onchange=change;change()}
async function compressPhoto(file){if(!file||file.size>25*1024*1024)throw Error('Choose a picture under 25 MB.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;try{await img.decode()}catch{throw Error('This picture cannot be opened. Try JPEG or PNG.')}let scale=Math.min(1,1200/Math.max(img.width,img.height));const c=document.createElement('canvas');for(let i=0;i<8;i++){c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));const ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);const blob=await new Promise(r=>c.toBlob(r,'image/jpeg',0.8));if(blob&&blob.size<=512000)return blob;scale*=0.75}throw Error('Could not compress this picture.')}finally{URL.revokeObjectURL(url)}}
async function readPreview(file){const blob=await compressPhoto(file);return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob)})}
async function pictureValue(prefix,w={}){const mode=$(prefix+'Mode').value;if(mode==='keep')return {photo_path:w.photo_path,image_url:null};if(mode==='link')return {photo_path:null,image_url:wishImage($(prefix+'Image').value)};if(mode==='none')return {photo_path:null,image_url:null};const blob=await compressPhoto($(prefix+'File').files[0]);const path=`${family.id}/${user.id}/${crypto.randomUUID()}.jpg`;const {error}=await sb.storage.from('wish-pictures').upload(path,blob,{contentType:'image/jpeg',upsert:false});if(error)throw error;return {photo_path:path,image_url:null}}
async function removePhoto(path){if(path)await sb.storage.from('wish-pictures').remove([path])}
async function savePicture(prefix,w,save){const value=await pictureValue(prefix,w);try{await save(value)}catch(e){if(value.photo_path!==w.photo_path)await removePhoto(value.photo_path);throw e}if(w.photo_path&&w.photo_path!==value.photo_path)await removePhoto(w.photo_path)}
function wireShopping(){document.querySelectorAll('.wish-photo[role="button"]').forEach(img=>{const open=()=>{const d=document.createElement('dialog');const pic=document.createElement('img');pic.src=img.src;pic.alt=img.alt;pic.style='max-width:85vw;max-height:75vh;object-fit:contain';const close=document.createElement('button');close.textContent='Close';close.onclick=()=>d.close();d.append(pic,close);document.body.append(d);d.onclose=()=>d.remove();d.showModal()};img.onclick=open;img.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}}});if(!$('applyWishFilters'))return;wirePicture('wish');$('applyWishFilters').onclick=()=>{wishFilter={person:$('filterPerson').value,category:$('filterCategory').value,search:$('filterSearch').value,sort:$('filterSort').value};$('wishResults').innerHTML=wishResults();wire()};$('clearWishFilters').onclick=()=>{wishFilter={person:'',category:'',search:'',sort:'default'};render()};document.querySelectorAll('[data-edit-wish]').forEach(b=>b.onclick=()=>{const w=wishes.find(x=>String(x.id)===b.dataset.editWish&&x.owner_id===user.id);if(!w)return;const d=document.createElement('dialog');d.innerHTML=`<h3>Edit wish details</h3><label>Estimated price ($)</label><input id="editPrice" type="number" min="0" step="0.01" value="${esc(w.estimated_price??'')}">${pictureFields('edit',w)}<p id="editError" role="status"></p><button id="editSave">Save details</button><button id="editCancel" class="secondary">Cancel</button>`;document.body.append(d);d.onclose=()=>d.remove();d.showModal();wirePicture('edit',w);$('editCancel').onclick=()=>d.close();$('editSave').onclick=async()=>{const btn=$('editSave');btn.disabled=true;try{const price=wishPrice($('editPrice').value);await savePicture('edit',w,async value=>{const {error}=await sb.from('wishes').update({estimated_price:price,...value}).eq('id',w.id).eq('owner_id',user.id);if(error)throw error});d.close();await refresh()}catch(e){if($('editError'))$('editError').textContent=e.message;else fail(e)}finally{btn.disabled=false}}})}
function viewVault(){let others=members.filter(m=>m.user_id!==user.id);return `<h2>🔒 Secret Gift Vault</h2><p class="muted">Only you can read these notes. Recipients cannot see your ideas, shopping progress, or gift details. Notes are private to your account, not shared with other shoppers.</p>${card(`<h3>New secret gift idea</h3><label>Recipient</label><select id="vaultRecipient">${others.map(m=>`<option value="${m.user_id}">${esc(m.display_name)}</option>`).join('')}</select><label>Gift idea</label><input id="vaultIdea" maxlength="500" placeholder="The perfect surprise..."><label>Private details</label><textarea id="vaultDetails" maxlength="3000" placeholder="Store, size, budget, notes..."></textarea><button id="vaultAdd" class="pink" ${others.length?'':'disabled'}>Save privately</button>`)}${vault.map(v=>card(`<h3>${esc(v.idea)}</h3><div class="muted">For ${esc(name(v.recipient_id))}</div><p>${esc(v.details)}</p><label>Progress</label><select data-vault-status="${v.id}">${[['idea','Idea'],['planned','Planned'],['purchased','Purchased'],['wrapped','Wrapped'],['given','Given']].map(([k,l])=>`<option value="${k}" ${v.status===k?'selected':''}>${l}</option>`).join('')}</select><button class="secondary" data-vault-delete="${v.id}">Delete note</button>`)).join('')||'<p class="muted">No secret notes yet.</p>'}`}
function viewDna(){let d=dna.find(x=>x.user_id===user.id)||{};return `<h2>🧬 Gift DNA</h2>${card(`<h3>Your gift personality</h3><label>Favorites, interests, brands</label><textarea id="favorites">${esc(d.favorites)}</textarea><label>Sizes and preferences</label><textarea id="sizes">${esc(d.sizes)}</textarea><label>No-Go list</label><textarea id="nogo">${esc(d.no_go)}</textarea><button id="saveDna">Save my profile</button>`)}${members.filter(m=>m.user_id!==user.id).map(m=>{let d=dna.find(x=>x.user_id===m.user_id)||{};return card(`<h3>${esc(m.display_name)}</h3><p><b>Favorites:</b> ${esc(d.favorites||'Not shared')}</p><p><b>Preferences:</b> ${esc(d.sizes||'Not shared')}</p><p><b>No-Go:</b> ${esc(d.no_go||'Not shared')}</p>`)}).join('')}`}
function viewBattles(){return `<h2>🎲 Gift Battles</h2>${card(`<h3>Start a family poll</h3><input id="optionA" maxlength="100" placeholder="Option A"><input id="optionB" maxlength="100" placeholder="Option B"><button id="addBattle" class="pink">Create battle</button>`)}${battles.map(b=>{let v=votes.filter(v=>v.battle_id===b.id);return card(`<h3>${esc(b.option_a)} vs. ${esc(b.option_b)}</h3><p class="muted">${v.filter(x=>x.choice==='a').length} votes vs. ${v.filter(x=>x.choice==='b').length} votes</p><button data-vote="${b.id}:a">Vote A</button><button class="secondary" data-vote="${b.id}:b">Vote B</button>`)}).join('')}`}
function viewFamily(){return `<h2>👨‍👩‍👧‍👦 Family</h2>${circleForm(me()?.display_name||family.displayName||'')}${card(`<h3>Members</h3>${members.map(m=>`<div class="item row"><span>${esc(m.display_name)} <span class="pill">${esc(m.role)}</span></span>${me()?.role==='admin'&&m.user_id!==user.id?`<button class="secondary" data-admin="${m.user_id}">${m.role==='admin'?'Make member':'Make admin'}</button>`:''}</div>`).join('')}`)}${me()?.role==='admin'?card(`<h3>✉️ Invite a family member</h3><p class="muted">Each invite is single-use and expires after 7 days. Share privately.</p><button id="makeInvite">Generate invitation</button><div id="inviteOutput"></div>`):''}${card(`<h3>App updates</h3><button id="manualUpdate" onclick="window.GiftUpdates?.check(true)">Check for updates</button><button class="secondary" onclick="window.GiftUpdates?.notes()">What’s new</button><p id="updateStatus" role="status"></p><h3>🔒 Privacy & current limitations</h3><p>Gift Happens V${esc(window.GiftUpdates?.version||'16.2.0')} · ${esc(window.GiftUpdates?.release||'Account Center')}</p><p>Secure accounts and shared wishlists are active. Reservations are recipient-hidden. Secret Gift Vault is active. Gift Circles are active. Weekly challenges and XP are active.</p><p class="muted">Circle members must be invited to their respective circle. The website itself is public, but data access is restricted by login and database policies.</p>`)}`}
async function mutate(fn){await run(async()=>{await fn();await refresh()})}function wire(){wireShopping();let b=id=>$(id);if(b('vaultAdd'))b('vaultAdd').onclick=()=>mutate(async()=>{let idea=b('vaultIdea').value.trim();if(!idea)throw Error('Enter a gift idea');let {error}=await sb.from('gift_vault').insert({family_id:family.id,author_id:user.id,recipient_id:b('vaultRecipient').value,idea,details:b('vaultDetails').value});if(error)throw error});document.querySelectorAll('[data-vault-status]').forEach(x=>x.onchange=()=>mutate(async()=>{let {error}=await sb.from('gift_vault').update({status:x.value}).eq('id',x.dataset.vaultStatus).eq('author_id',user.id);if(error)throw error}));document.querySelectorAll('[data-vault-delete]').forEach(x=>x.onclick=()=>mutate(async()=>{if(!confirm('Delete this private note?'))return;let {error}=await sb.from('gift_vault').delete().eq('id',x.dataset.vaultDelete).eq('author_id',user.id);if(error)throw error}));if(b('addWish'))b('addWish').onclick=()=>mutate(async()=>{let title=b('wishTitle').value.trim();if(!title)throw Error('Enter a gift idea');let link=b('wishLink').value.trim();if(link&&!/^https:\/\//i.test(link))throw Error('Use an https:// product link');const price=wishPrice(b('wishPrice').value),category=b('wishCategory').value;await savePicture('wish',{},async value=>{let {error}=await sb.from('wishes').insert({family_id:family.id,owner_id:user.id,title,category,link,estimated_price:price,...value});if(error)throw error})});if(b('saveDna'))b('saveDna').onclick=()=>mutate(async()=>{let {error}=await sb.from('gift_dna').upsert({family_id:family.id,user_id:user.id,favorites:b('favorites').value,sizes:b('sizes').value,no_go:b('nogo').value});if(error)throw error});if(b('addBattle'))b('addBattle').onclick=()=>mutate(async()=>{let a=b('optionA').value.trim(),c=b('optionB').value.trim();if(!a||!c)throw Error('Enter both choices');let {error}=await sb.from('battles').insert({family_id:family.id,created_by:user.id,option_a:a,option_b:c});if(error)throw error});if(b('makeInvite'))b('makeInvite').onclick=()=>run(async()=>{let {data,error}=await sb.rpc('make_invite',{fid:family.id});if(error)throw error;b('inviteOutput').innerHTML=`<p>Single-use invite code:</p><code>${esc(data)}</code><p class="muted">Send this code privately. They create an account and paste it into Join family.</p>`});document.querySelectorAll('[data-delete]').forEach(x=>x.onclick=()=>mutate(async()=>{if(!confirm('Remove this wish?'))return;const w=wishes.find(w=>String(w.id)===x.dataset.delete);let {error}=await sb.from('wishes').delete().eq('id',x.dataset.delete);if(error)throw error;await removePhoto(w?.photo_path)}));for(let action of ['reserve','unreserve'])document.querySelectorAll(`[data-${action}]`).forEach(x=>x.onclick=()=>mutate(async()=>{let {error}=await sb.rpc(action==='reserve'?'reserve_wish':'unreserve_wish',{wid:x.dataset[action]});if(error)throw error}));document.querySelectorAll('[data-vote]').forEach(x=>x.onclick=()=>mutate(async()=>{let [battle_id,choice]=x.dataset.vote.split(':');let {error}=await sb.from('votes').upsert({battle_id,user_id:user.id,choice});if(error)throw error}));document.querySelectorAll('[data-admin]').forEach(x=>x.onclick=()=>mutate(async()=>{let m=members.find(m=>m.user_id===x.dataset.admin);if(!confirm(`Change ${m.display_name}'s role?`))return;let {error}=await sb.rpc('set_member_role',{fid:family.id,target:m.user_id,new_role:m.role==='admin'?'member':'admin'});if(error)throw error}))}
// Refresh on return to tab and periodically while open (no secrets in localStorage beyond Supabase session).
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&family&&tab==='home'&&!document.querySelector('#app input:focus,#app textarea:focus,#app select:focus'))run(refresh)});setInterval(()=>{if(family&&!document.hidden&&tab==='home'&&!document.querySelector('#app input:focus,#app textarea:focus,#app select:focus'))run(refresh)},30000);

function viewSanta(){return `<section class="hero"><small>TOP SECRET · FAMILY EXCHANGE</small><h2>🎅 Secret Santa</h2><p>One mission. One lucky recipient. No spoilers.</p></section><div id="santaContent">Loading exchanges…</div>`}
async function loadSanta(){let fid=family.id, uid=user.id, el=$('santaContent');try{let [a,b]=await Promise.all([sb.from('santa_exchanges').select('*').eq('family_id',fid).order('exchange_date'),sb.from('santa_assignments').select('*').eq('giver',uid)]);if(a.error)throw a.error;if(b.error)throw b.error;if(el!==$('santaContent')||family?.id!==fid||user?.id!==uid)return;let admin=me()?.role==='admin';let opts=members.map(m=>`<option value="${m.user_id}">${esc(m.display_name)}</option>`).join('');el.innerHTML=(admin?card(`<h3>✨ Create an exchange</h3><label>Exchange name</label><input id="sTitle" maxlength="100" value="Family Christmas"><label>Budget ($)</label><input id="sBudget" type="number" min="0" value="75"><label>Exchange date</label><input id="sDate" type="date"><h3>Participants</h3>${members.map(m=>`<label style="display:flex;align-items:center;gap:8px"><input style="width:auto;margin:5px" type="checkbox" data-s-person="${m.user_id}" checked>${esc(m.display_name)}</label>`).join('')}<h3>Exclusions</h3><p class="muted">Prevent one person from drawing another. Add both directions if needed.</p><select id="sFrom">${opts}</select><select id="sTo">${opts}</select><button id="sBlock" class="secondary">Add exclusion</button><div id="sBlocks"></div><button id="sCreate" class="pink">Create exchange</button>`):'')+a.data.map(e=>{let x=b.data.find(x=>x.exchange_id===e.id),days=Math.ceil((new Date(e.exchange_date+'T00:00:00')-new Date().setHours(0,0,0,0))/86400000);return card(`<h3>🎁 ${esc(e.title)}</h3><p>$${Number(e.budget).toFixed(2)} budget · ${esc(e.exchange_date)} · ${days>=0?days+' days left':'Date passed'}</p><p class="muted">${e.participants.length} participants · ${e.drawn?'Draw complete':'Awaiting draw'}</p>${x?`<div class="notice"><h3>Your secret recipient: ${esc(name(x.recipient))}</h3><button data-person="${x.recipient}">View gift profile</button><label>Private shopping progress</label><select data-s-status="${e.id}">${['idea','purchased','ready'].map(k=>`<option ${x.status===k?'selected':''}>${k}</option>`).join('')}</select></div>`:e.participants.includes(uid)?'<p>Your assignment will appear after the draw.</p>':'<p>You are not participating.</p>'}${admin?`${!e.drawn?`<button data-s-draw="${e.id}" class="pink">Draw names</button>`:''}<button class="secondary" data-s-delete="${e.id}">Delete exchange</button>`:''}`)}).join('')+(a.data.length?'':'<p class="muted">No exchanges yet.</p>');let blocked=[];if(admin){$('sBlock').onclick=()=>{let a=$('sFrom').value,b=$('sTo').value;if(a===b)return;blocked.push([a,b]);$('sBlocks').textContent=blocked.map(([a,b])=>name(a)+' cannot draw '+name(b)).join(' · ')};$('sCreate').onclick=()=>action(async()=>{let {error}=await sb.rpc('santa_create',{fid,label:$('sTitle').value.trim(),amount:Number($('sBudget').value),day:$('sDate').value,people:[...el.querySelectorAll('[data-s-person]:checked')].map(x=>x.dataset.sPerson),blocked});if(error)throw error})}function action(fn){run(async()=>{await fn();await loadSanta()})}el.querySelectorAll('[data-s-draw]').forEach(x=>x.onclick=()=>{if(confirm('Draw names now? Assignments cannot be redrawn.'))action(async()=>{let {error}=await sb.rpc('santa_draw',{eid:x.dataset.sDraw});if(error)throw error})});el.querySelectorAll('[data-s-delete]').forEach(x=>x.onclick=()=>{if(confirm('Permanently delete this exchange and assignments?'))action(async()=>{let {error}=await sb.rpc('santa_delete',{eid:x.dataset.sDelete});if(error)throw error})});el.querySelectorAll('[data-s-status]').forEach(x=>x.onchange=()=>action(async()=>{let {error}=await sb.from('santa_assignments').update({status:x.value}).eq('exchange_id',x.dataset.sStatus).eq('giver',uid);if(error)throw error}));el.querySelectorAll('[data-person]').forEach(x=>x.onclick=()=>{navigate('person',x.dataset.person)})}catch(e){if(el===$('santaContent'))el.textContent='Secret Santa unavailable: '+(e.message||e)}}

function viewIntel(){return `<section class="hero"><small>CLASSIFIED · GIFT INTELLIGENCE</small><h2>🕵️ Gift Intelligence</h2><p>Collect clues. Find brilliant gifts. Keep the surprise.</p></section><div id="intelContent">Loading…</div>`}
async function loadIntel(){const el=$('intelContent'), fid=family.id, uid=user.id;try{const [a,b]=await Promise.all([sb.from('gift_intel_notes').select('*').eq('family_id',fid).order('created_at',{ascending:false}),sb.rpc('intel_questions',{fid})]);if(a.error)throw a.error;if(b.error)throw b.error;if(el!==$('intelContent')||family?.id!==fid||user?.id!==uid)return;const opts=members.filter(m=>m.user_id!==uid).map(m=>`<option value="${esc(m.user_id)}">${esc(m.display_name)}</option>`).join('');const link=v=>/^https:\/\//i.test(v||'')?`<a href="${esc(v)}" target="_blank" rel="noopener noreferrer">Product link</a>`:'';el.innerHTML=card(`<h3>🔎 Gift Detective</h3><p class="muted">Investigate shared wishlists, preferences and No-Go lists.</p>${members.filter(m=>m.user_id!==uid).map(m=>`<button class="secondary" data-person="${esc(m.user_id)}">${avatar(m)} ${esc(m.display_name)}</button>`).join('')}`)+card(`<h3>📓 Add Gift Intel / Spotted in the Wild</h3><p class="muted">Visible to other family members, not the intended recipient.</p><label>For</label><select id="iTarget">${opts}</select><label>Type</label><select id="iKind"><option value="clue">Gift Intel</option><option value="spot">Spotted in the Wild</option></select><label>Clue or item</label><textarea id="iBody" maxlength="1000"></textarea><label>Store / price (optional)</label><input id="iDetail" maxlength="200"><label>Product link (optional)</label><input id="iLink" type="url" maxlength="2000"><button id="iAdd" class="pink">Save clue</button>`)+card(`<h3>🗂️ Family intelligence</h3>${a.data.map(n=>`<div class="item"><span class="pill">${n.kind==='spot'?'📸 Spotted':'📓 Clue'}</span><p><b>For ${esc(name(n.target_id))}</b> · from ${esc(name(n.author_id))}</p><p>${esc(n.body)}</p><p class="muted">${esc(n.detail)}</p>${link(n.link)}${n.author_id===uid?`<button class="secondary" data-i-delete="${n.id}">Delete</button>`:''}</div>`).join('')||'<p class="muted">No clues yet.</p>'}`)+card(`<h3>✉️ Anonymous gift questions</h3><p class="muted">The recipient does not see who asked. Answers are private to the asker and recipient.</p><label>Ask</label><select id="qTarget">${opts}</select><textarea id="qBody" maxlength="500" placeholder="What is your favorite…?"></textarea><button id="qAdd">Send anonymously</button>`)+card(`<h3>📬 Questions</h3>${b.data.map(q=>`<div class="item"><b>${q.incoming?'Anonymous question':'To '+esc(name(q.target_id))}</b><p>${esc(q.body)}</p>${q.answer!==null?`<p>Answer: ${esc(q.answer)}</p>`:q.incoming?`<textarea id="answer-${q.id}" maxlength="1000" placeholder="Your answer"></textarea><button data-q-answer="${q.id}">Reply</button>`:'<p class="muted">Waiting for an answer</p>'}${!q.incoming?`<button class="secondary" data-q-delete="${q.id}">Delete</button>`:''}</div>`).join('')||'<p class="muted">No questions yet.</p>'}`);function action(fn){run(async()=>{const r=await fn();if(r.error)throw r.error;await loadIntel()})}el.querySelectorAll('[data-person]').forEach(x=>x.onclick=()=>{navigate('person',x.dataset.person)});$('iAdd').onclick=()=>action(()=>{let body=$('iBody').value.trim(),url=$('iLink').value.trim();if(!body||!$('iTarget').value)throw Error('Choose a recipient and enter a clue');if(url&&!/^https:\/\//i.test(url))throw Error('Use an https:// link');return sb.from('gift_intel_notes').insert({family_id:fid,author_id:uid,target_id:$('iTarget').value,kind:$('iKind').value,body,detail:$('iDetail').value,link:url})});$('qAdd').onclick=()=>action(()=>sb.rpc('intel_ask',{fid,target:$('qTarget').value,question:$('qBody').value.trim()}));el.querySelectorAll('[data-i-delete]').forEach(x=>x.onclick=()=>{if(confirm('Delete clue?'))action(()=>sb.from('gift_intel_notes').delete().eq('id',x.dataset.iDelete))});el.querySelectorAll('[data-q-answer]').forEach(x=>x.onclick=()=>action(()=>sb.rpc('intel_answer',{qid:x.dataset.qAnswer,reply:$('answer-'+x.dataset.qAnswer).value.trim()})));el.querySelectorAll('[data-q-delete]').forEach(x=>x.onclick=()=>{if(confirm('Delete question?'))action(()=>sb.rpc('intel_delete_question',{qid:x.dataset.qDelete}))});}catch(e){if(el===$('intelContent'))el.textContent='Gift Intelligence unavailable: '+e.message}}

const chaosPrompts=[
'Three things you’d buy if you won $500 today','Three guilty pleasures you secretly want','Three things that scream “this is so me”','Three experiences you would love to try','Three gifts that would make your 12-year-old self lose their mind','Three upgrades you keep putting off','Three things you want but refuse to pay full price for','Three ridiculous things you would buy with unlimited money','Three gifts that would instantly improve a rainy day','Three things you would grab in a five-minute shopping spree','Three things you love that nobody in the family knows about','Three items for your dream weekend','Three things you would want for a new hobby','Three gifts that would make you say “how did you know?”','Three things you would put in your own mystery gift box','Three things that belong in your ideal game night','Three small luxuries you would use every week','Three things you would bring to a deserted island (no survival gear)','Three things you miss from childhood','Three things you would love to collect','Three things for your dream road trip','Three things that feel too extra to ask for','Three gifts you would share with someone else','Three things that would make Monday less awful','Three items for your ideal cozy night in','Three things you want to learn or try','Three things you would buy at an airport with a $200 voucher','Three gifts inspired by your favorite movie or song','Three things you have saved in a shopping cart forever','Three things you want but have never mentioned aloud','Three things that would make your workspace better','Three things you would put on a birthday wishlist today','Three unexpected gifts that would genuinely delight you','Three things that would make your next vacation better','Three gifts you would never predict someone would choose for you','Three things that would make you laugh every time you saw them'];
function viewChaos(){return `<section class="hero"><small>FAMILY CHAOS</small><h2>🎲 Wildcard Wednesday</h2><p>Three answers. No spoilers until next Wednesday.</p></section><button data-tab="battle">🎲 Gift Battles</button><div id="chaosContent" class="card">Loading…</div>`}
async function loadChaos(){const el=$('chaosContent'),fid=family.id,uid=user.id;try{const r=await sb.rpc('chaos_state',{fid});if(r.error)throw r.error;if(el!==$('chaosContent')||family?.id!==fid||user?.id!==uid)return;const d=r.data,w=d.week,prompt=n=>chaosPrompts[((n%36)+36)%36];const own=d.entries.find(x=>x.week===w&&x.user_id===uid);const current=d.entries.filter(x=>x.week===w);el.innerHTML=`<h3>This week's challenge</h3><div class="coming"><b>${esc(prompt(w))}</b></div><p class="muted">${d.count} / ${members.length} submitted · Reveal Wednesday at midnight Eastern</p><form id="chaosForm">${[0,1,2].map(i=>`<label>Answer ${i+1}<input id="chaos${i}" required maxlength="250" value="${esc(own?.answers?.[i]||'')}"></label>`).join('')}<button class="pink">${own?'Update answers':'Submit answers'}</button></form><h3>🏆 Family leaderboard</h3>${d.scores.map((s,i)=>`<div class="item"><b>${i+1}. ${esc(name(s.user_id))}</b> · ${s.xp} XP ${s.xp>=250?'🏅 Chaos Legend':s.xp>=100?'⭐ Gift Pro':s.xp>=25?'🎉 First Challenge':''}</div>`).join('')}<h3>Previous reveals</h3>${d.entries.filter(x=>x.week<w).map(x=>`<div class="item"><b>${esc(name(x.user_id))}</b><p class="muted">${esc(prompt(x.week))}</p>${x.answers.map(t=>`<p>• ${esc(t)}</p>`).join('')}</div>`).join('')||'<p class="muted">No revealed answers yet.</p>'}`;$('chaosForm').onsubmit=e=>{e.preventDefault();run(async()=>{const b=e.target.querySelector('button');b.disabled=true;try{const r=await sb.rpc('chaos_submit',{fid,expected_week:w,answers:[0,1,2].map(i=>$('chaos'+i).value.trim())});if(r.error)throw r.error;await loadChaos()}finally{b.disabled=false}})}}catch(e){if(el===$('chaosContent'))el.textContent='Family Chaos unavailable: '+e.message}}

function celebrationDate(c){const today=new Date();const base=new Date(c.day+'T00:00:00');today.setHours(0,0,0,0);if(c.annual){const dateFor=y=>new Date(y,base.getMonth(),Math.min(base.getDate(),new Date(y,base.getMonth()+1,0).getDate()));let d=dateFor(today.getFullYear());if(d<today)d=dateFor(today.getFullYear()+1);return d;}return base;}
function celebrationDays(c){let t=new Date(),d=celebrationDate(c);return Math.round((Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())-Date.UTC(t.getFullYear(),t.getMonth(),t.getDate()))/86400000)}
function celebrationLabel(c){let n=celebrationDays(c);return `${celebrationDate(c).toLocaleDateString()} · ${n===0?'Today!':n>0?n+' days away':'Past occasion'}`}
async function celebrationRows(){return query('celebrations','*',true)}
async function loadUpcoming(){const el=$('upcomingCelebrations'),fid=family.id;try{const rows=await celebrationRows();if(el!==$('upcomingCelebrations')||family?.id!==fid)return;const next=rows.filter(c=>celebrationDays(c)>=0).sort((a,b)=>celebrationDays(a)-celebrationDays(b)).slice(0,3);el.innerHTML=card(`<h3>🎉 Upcoming celebrations</h3>${next.map(c=>`<div class="item"><b>${esc(c.title)}</b><p class="muted">${esc(celebrationLabel(c))}</p></div>`).join('')||'<p class="muted">No upcoming occasions yet.</p>'}<button data-celebration-open>Open calendar</button>`);el.querySelector('[data-celebration-open]').onclick=()=>{navigate('celebrations')}}catch(e){if(el=== $('upcomingCelebrations'))el.textContent='Celebrations unavailable: '+(e.message||e)}}
function viewCelebrations(){return `<section class="hero"><small>MAKE EVERY OCCASION COUNT</small><h2>🎉 Celebrations</h2><p>Plan ahead. Spend wisely. Keep surprises secret.</p></section><div id="celebrationContent">Loading calendar…</div>`}
async function loadCelebrations(){const el=$('celebrationContent'),fid=family.id,uid=user.id;try{const [rows,p,w]=await Promise.all([celebrationRows(),sb.from('celebration_plans').select('*').eq('owner',uid),sb.from('celebration_wishes').select('*')]);if(p.error)throw p.error;if(w.error)throw w.error;const plans=p.data||[],g=plans.length?await sb.from('celebration_gifts').select('*').in('plan',plans.map(x=>x.id)):{data:[]};if(g.error)throw g.error;if(el!==$('celebrationContent')||family?.id!==fid||user?.id!==uid)return;const options=members.map(m=>`<option value="${esc(m.user_id)}">${esc(m.display_name)}</option>`).join('');const money=n=>Number(n).toLocaleString('en-US',{style:'currency',currency:'USD'});const sorted=rows.sort((a,b)=>(celebrationDays(a)<0)-(celebrationDays(b)<0)||celebrationDays(a)-celebrationDays(b));el.innerHTML=card(`<h3>Add an occasion</h3><form id="occasionAdd"><label>Occasion name</label><input name="title" required maxlength="120"><label>Type</label><select name="kind"><option>Birthday</option><option>Holiday</option><option>Anniversary</option><option>Other</option></select><label>Date</label><input name="day" type="date" required><label>Celebrating</label><select name="person"><option value="">Everyone</option>${options}</select><label><input style="width:auto;display:inline" type="checkbox" name="annual"> Repeat annually</label><button class="pink">Add occasion</button></form>`)+sorted.map(c=>{const plan=plans.find(x=>x.occasion===c.id),gifts=(g.data||[]).filter(x=>x.plan===plan?.id),spent=gifts.filter(x=>x.stage!=='idea').reduce((s,x)=>s+Number(x.cost),0),ws=(w.data||[]).filter(x=>x.occasion===c.id);return card(`<h3>${esc(c.title)}</h3><p class="muted">${esc(c.kind)} · ${esc(celebrationLabel(c))}${c.annual?' · Annual':''}${c.person?' · '+esc(name(c.person)):''}</p><details><summary>🎁 Occasion wishlists</summary>${ws.map(x=>`<div class="item">${esc(name(x.owner))}: ${esc(x.title)} ${x.owner===uid?`<button data-cwish-delete="${esc(x.id)}">Remove</button>`:''}</div>`).join('')||'<p>No wishes yet.</p>'}<form data-cwish="${esc(c.id)}"><input name="title" required maxlength="250" placeholder="Add your wish"><button>Add wish</button></form></details><details><summary>🔒 My private budget & gift history</summary><p>Budget: ${money(plan?.budget||0)} · Spent: ${money(spent)} · Remaining: ${money(Number(plan?.budget||0)-spent)}</p><form data-budget="${esc(c.id)}"><label>Budget ($)</label><input name="budget" type="number" min="0" max="9999999999" step="0.01" required value="${esc(plan?.budget||0)}"><button>Save budget</button></form>${gifts.map(x=>`<div class="item"><b>${esc(x.title)}</b> · ${esc(name(x.recipient))} · ${money(x.cost)} · ${esc(x.stage)} <button data-gift-delete="${esc(x.id)}">Remove</button></div>`).join('')}${plan?`<form data-cgift="${esc(plan.id)}"><label>Recipient</label><select name="recipient">${options}</select><label>Purchased gift</label><input name="title" required maxlength="250"><label>Cost ($)</label><input name="cost" type="number" min="0" max="9999999999" step="0.01" required><button class="pink">Record purchase</button></form>`:'<p class="muted">Save a budget first to record purchases.</p>'}</details>${c.creator===uid||me()?.role==='admin'?`<button class="secondary" data-occasion-delete="${esc(c.id)}">Delete occasion</button>`:''}`)}).join('');
const save=async op=>{await run(async()=>{const r=await op();if(r.error)throw r.error;if(el===$('celebrationContent'))await loadCelebrations()})};const form=(selector,fn)=>el.querySelectorAll(selector).forEach(f=>f.onsubmit=e=>{e.preventDefault();const d=new FormData(f);save(()=>fn(f,d))});form('#occasionAdd',(f,d)=>sb.from('celebrations').insert({family_id:fid,title:d.get('title').trim(),kind:d.get('kind'),day:d.get('day'),person:d.get('person')||null,annual:d.has('annual')}));form('[data-cwish]',(f,d)=>sb.from('celebration_wishes').insert({occasion:f.dataset.cwish,title:d.get('title').trim()}));form('[data-budget]',(f,d)=>sb.from('celebration_plans').upsert({occasion:f.dataset.budget,owner:uid,budget:Number(d.get('budget'))},{onConflict:'occasion,owner'}));form('[data-cgift]',(f,d)=>sb.from('celebration_gifts').insert({plan:f.dataset.cgift,recipient:d.get('recipient'),title:d.get('title').trim(),cost:Number(d.get('cost'))}));for(const [attr,table] of [['cwish-delete','celebration_wishes'],['gift-delete','celebration_gifts'],['occasion-delete','celebrations']])el.querySelectorAll(`[data-${attr}]`).forEach(b=>b.onclick=()=>{if(confirm(attr==='occasion-delete'?'Delete this occasion and all associated wishes, budgets and purchase history for everyone?':'Remove this entry?'))save(()=>sb.from(table).delete().eq('id',b.getAttribute('data-'+attr)))});
}catch(e){if(el===$('celebrationContent'))el.textContent='Unable to load celebrations: '+(e.message||e)}}

const avatarChoices=['🎧','✨','🎮','🎨','⚾','💜','🌟','🎁','🐱','🐶','🦊','🐻','🐉','🦄','🌈','☕','📚','🎬','🎸','🏀','🌻','🍕','👑','🚀','🦋','🌙','🎄','😎','🍓','🪩','🧁','🐸'];
function viewProfile(){return `<h2>👤 My profile</h2>${card(`<h3>${avatar(me())} ${esc(me().display_name)}</h3><p>Choose your Crew avatar. It will appear for everyone in this family.</p><div class="avatar-grid">${avatarChoices.map(a=>`<button type="button" class="avatar-choice ${a===avatar(me())?'chosen':''}" aria-label="Choose ${a}" aria-pressed="${a===avatar(me())}" data-avatar="${a}">${a}</button>`).join('')}</div><p id="profileStatus" role="status"></p>`)}${card(`<h3>Quick settings</h3><button data-tab="dna">Edit Gift DNA</button><button data-tab="family" class="secondary">Family settings</button><p class="muted">Gift Happens 16.2.0</p>`)}`}
function wireProfile(){document.querySelectorAll('[data-avatar]').forEach(b=>b.onclick=()=>run(async()=>{const r=await sb.from('gift_profiles').upsert({family_id:family.id,user_id:user.id,avatar:b.dataset.avatar},{onConflict:'family_id,user_id'});if(r.error)throw r.error;await refresh();if($('profileStatus'))$('profileStatus').textContent='Avatar saved!'}))}
async function loadDashboard(){const el=$('personalDashboard'),fid=family.id,uid=user.id;if(!el)return;const own=wishes.filter(w=>w.owner_id===uid).length, pending=vault.filter(v=>!['wrapped','given'].includes(v.status)).length;el.innerHTML=card(`<div class="row"><h3>${avatar(me())} My dashboard</h3><button class="secondary" id="profileOpen">Edit avatar</button></div><div class="dashboard-grid"><button data-dash="wishes"><strong>${own}</strong>My wishes</button><button data-dash="vault"><strong>${pending}</strong>Private gifts to finish</button><button data-dash="wishes"><strong>${mine.size}</strong>My reservations</button></div><h3>🔔 My reminders</h3><div id="dashReminders" class="muted">Checking your questions…</div><button data-dash="chaos">Weekly challenge</button><button data-dash="santa">Secret Santa</button><button data-dash="celebrations">My budgets</button>`);function go(t){navigate(t)}el.querySelector('#profileOpen').onclick=()=>go('profile');el.querySelectorAll('[data-dash]').forEach(b=>b.onclick=()=>go(b.dataset.dash));try{const r=await sb.rpc('intel_questions',{fid});if(r.error)throw r.error;if(el!==$('personalDashboard')||family?.id!==fid||user?.id!==uid)return;const count=r.data.filter(q=>q.incoming&&q.answer===null).length;const answered=r.data.filter(q=>!q.incoming&&q.answer!==null).length;const dest=el.querySelector('#dashReminders');dest.innerHTML=`<p>${count?`${count} anonymous question(s) awaiting your reply`:'No unanswered questions'}</p><p>${answered} answered question(s) in your inbox</p><button class="secondary" id="dashInbox">Open questions</button>`;dest.querySelector('#dashInbox').onclick=()=>go('intel')}catch(e){if(el===$('personalDashboard'))el.querySelector('#dashReminders').textContent='Reminders unavailable; open Gift Intelligence to retry.'}}
let plannerOccasion='', plannerRecipient='', plannerFilter='all';
function viewPlanner(){return `<section class="hero"><small>FOR YOUR EYES ONLY</small><h2>🛍️ Gift Planning Pro</h2><p>Ideas, shopping, wrapping and budgets in one place.</p></section><div id="plannerContent">Loading your private planner…</div>`}
async function loadPlanner(){const el=$('plannerContent'),fid=family.id,uid=user.id;const active=()=>el===$('plannerContent')&&family?.id===fid&&user?.id===uid;try{
const rows=await celebrationRows();if(!active())return;if(!rows.length){el.innerHTML=card('<p>Create an occasion first.</p><button id="plannerCalendar">Open Celebrations</button>');el.querySelector('button').onclick=()=>{navigate('celebrations')};return}
if(!rows.some(c=>c.id===plannerOccasion))plannerOccasion=rows.slice().sort((a,b)=>(celebrationDays(a)<0)-(celebrationDays(b)<0)||celebrationDays(a)-celebrationDays(b))[0].id;
const oid=plannerOccasion;const pr=await sb.from('celebration_plans').select('*').eq('occasion',oid).eq('owner',uid).maybeSingle();if(pr.error)throw pr.error;const plan=pr.data;let gifts=[],budgets=[];if(plan){const [g,b]=await Promise.all([sb.from('celebration_gifts').select('*').eq('plan',plan.id),sb.from('recipient_budgets').select('*').eq('plan',plan.id)]);if(g.error)throw g.error;if(b.error)throw b.error;gifts=g.data;budgets=b.data}if(!active()||oid!==plannerOccasion)return;
const money=n=>Number(n||0).toLocaleString('en-US',{style:'currency',currency:'USD'}),total=a=>a.reduce((s,x)=>s+Number(x.cost),0), purchased=a=>total(a.filter(x=>x.stage!=='idea')), stages=['idea','purchased','wrapped','given'], options=members.map(m=>`<option value="${esc(m.user_id)}">${esc(m.display_name)}</option>`).join('');
const visible=gifts.filter(g=>(!plannerRecipient||g.recipient===plannerRecipient)&&(plannerFilter==='all'||g.stage===plannerFilter));
el.innerHTML=card(`<label>Occasion</label><select id="plannerOccasion">${rows.map(c=>`<option value="${esc(c.id)}" ${c.id===oid?'selected':''}>${esc(c.title)} · ${esc(celebrationLabel(c))}</option>`).join('')}</select><p class="muted">Only you can see your planning and spending.</p><form id="plannerBudget"><label>Total budget ($)</label><input name="budget" type="number" min="0" max="9999999999" step=".01" required value="${esc(plan?.budget||0)}"><button>Save budget</button></form><div class="dashboard-grid"><div>Planned<br><strong>${money(total(gifts))}</strong></div><div>Spent<br><strong>${money(purchased(gifts))}</strong></div><div>Remaining<br><strong>${money(Number(plan?.budget||0)-purchased(gifts))}</strong></div></div><p>${gifts.filter(x=>x.stage!=='idea').length} of ${gifts.length} gifts purchased · ${gifts.filter(x=>['wrapped','given'].includes(x.stage)).length} wrapped or given</p>`)+ (plan?card(`<h3>Recipient budgets</h3>${members.map(m=>{const b=budgets.find(x=>x.recipient===m.user_id),g=gifts.filter(x=>x.recipient===m.user_id);return `<form data-rec-budget="${esc(m.user_id)}" class="item"><b>${esc(m.display_name)}</b><p>Planned ${money(total(g))} · Spent ${money(purchased(g))}${b?' · Remaining '+money(Number(b.amount)-purchased(g)):''}</p><label>Personal limit ($)</label><input name="amount" type="number" min="0" max="9999999999" step=".01" required value="${esc(b?.amount??'')}"><button>Save recipient limit</button></form>`}).join('')}`)+card(`<h3>Add gift to shopping list</h3><form id="plannerAdd"><label>Recipient</label><select name="recipient">${options}</select><label>Gift</label><input name="title" required maxlength="250"><label>Estimated or actual cost ($)</label><input name="cost" type="number" min="0" max="9999999999" step=".01" required><label>Status</label><select name="stage">${stages.map(x=>`<option>${x}</option>`).join('')}</select><button class="pink">Add gift</button></form>`)+card(`<h3>My shopping checklist</h3><label>Recipient</label><select id="plannerRecipient"><option value="">Everyone</option>${options}</select><label>Status</label><select id="plannerFilter"><option value="all">All statuses</option>${stages.map(x=>`<option>${x}</option>`).join('')}</select>${visible.map(g=>`<form data-planner-edit="${esc(g.id)}" class="item"><b class="planner-recipient">${esc(name(g.recipient))}</b><label>Gift</label><input name="title" required maxlength="250" value="${esc(g.title)}"><label>Cost ($)</label><input name="cost" type="number" min="0" max="9999999999" step=".01" required value="${esc(g.cost)}"><label>Status</label><select name="stage">${stages.map(x=>`<option ${x===g.stage?'selected':''}>${x}</option>`).join('')}</select><button>Save changes</button><button type="button" class="secondary" data-planner-delete="${esc(g.id)}">Remove</button></form>`).join('')||'<p>No matching gifts.</p>'}`):card('<p>Save a total budget first (zero is allowed) to start planning.</p>'));
const save=async(op)=>{await run(async()=>{const r=await op();if(r.error)throw r.error;if(active())await loadPlanner()})};const forms=(sel,fn)=>el.querySelectorAll(sel).forEach(f=>f.onsubmit=e=>{e.preventDefault();save(()=>fn(f,new FormData(f)))});
el.querySelector('#plannerOccasion').onchange=e=>{plannerOccasion=e.target.value;loadPlanner()};forms('#plannerBudget',(f,d)=>sb.from('celebration_plans').upsert({occasion:oid,owner:uid,budget:Number(d.get('budget'))},{onConflict:'occasion,owner'}));if(!plan)return;
for(const [id,val,set] of [['plannerRecipient',plannerRecipient,v=>plannerRecipient=v],['plannerFilter',plannerFilter,v=>plannerFilter=v]]){const s=el.querySelector('#'+id);s.value=val;s.onchange=e=>{set(e.target.value);loadPlanner()}}
forms('[data-rec-budget]',(f,d)=>sb.from('recipient_budgets').upsert({plan:plan.id,recipient:f.dataset.recBudget,amount:Number(d.get('amount'))},{onConflict:'plan,recipient'}));forms('#plannerAdd',(f,d)=>sb.from('celebration_gifts').insert({plan:plan.id,recipient:d.get('recipient'),title:d.get('title').trim(),cost:Number(d.get('cost')),stage:d.get('stage')}));forms('[data-planner-edit]',(f,d)=>sb.from('celebration_gifts').update({title:d.get('title').trim(),cost:Number(d.get('cost')),stage:d.get('stage')}).eq('id',f.dataset.plannerEdit).eq('plan',plan.id));el.querySelectorAll('[data-planner-delete]').forEach(b=>b.onclick=()=>{if(confirm('Remove this gift from your private plan?'))save(()=>sb.from('celebration_gifts').delete().eq('id',b.dataset.plannerDelete).eq('plan',plan.id))});
}catch(e){if(active())el.textContent='Unable to load planner: '+(e.message||e)}}

// V14: derived, circle-scoped reminders; no sensitive message contents in alerts.
function notificationKey(){return `gift-happens-notifications:${user.id}:${family.id}`}
const notificationDefaults={celebrations:true,santa:true,intel:true,chaos:true,battles:true};
function notificationState(){try{const x=JSON.parse(localStorage.getItem(notificationKey())||'{}');return {prefs:{...notificationDefaults,...x.prefs},read:Array.isArray(x.read)?x.read:[]}}catch{return {prefs:{...notificationDefaults},read:[]}}}
function saveNotificationState(x){try{localStorage.setItem(notificationKey(),JSON.stringify(x));return true}catch{return false}}
function viewNotifications(){return `<h2>🔔 Notification Center</h2><p class="muted">Private reminders for ${esc(family.name)}. Checked while the app is open.</p><div id="notificationContent">Checking reminders…</div>`}
async function loadNotifications(){const el=$('notificationContent')||$('notificationPreview'),fid=family.id,uid=user.id;if(!el)return;const full=el.id==='notificationContent';const state=notificationState();let entries=[],errors=[];const add=(kind,id,title,detail,dest)=>entries.push({kind,id:kind+':'+id,title,detail,dest});
const jobs=[['celebrations',async()=>{for(const c of await celebrationRows()){const days=celebrationDays(c);if(days>=0&&days<=14)add('celebrations',c.id+':'+celebrationDate(c).getFullYear()+':'+(days===0?'today':days<=3?'soon':'upcoming'),'🎉 '+c.title,days===0?'Today!':`${days} days away`,'celebrations')}}],['santa',async()=>{const [a,b]=await Promise.all([sb.from('santa_exchanges').select('*').eq('family_id',fid),sb.from('santa_assignments').select('exchange_id,status').eq('giver',uid)]);if(a.error)throw a.error;if(b.error)throw b.error;for(const e of a.data||[]){if(!e.participants.includes(uid))continue;const days=celebrationDays({day:e.exchange_date,annual:false});if(days<0)continue;const x=(b.data||[]).find(v=>v.exchange_id===e.id);if(x)add('santa',e.id+':draw','🎅 Your Secret Santa assignment is available','Open privately to see details.','santa');if(days<=7&&x?.status!=='ready')add('santa',e.id+':'+(days===0?'today':'week'),'🎁 Secret Santa exchange approaching',days===0?'Today':`${days} days away`,'santa')}}],['intel',async()=>{const r=await sb.rpc('intel_questions',{fid});if(r.error)throw r.error;for(const q of r.data||[]){if(q.incoming&&q.answer===null)add('intel',q.id+':question','✉️ Anonymous gift question','A question is waiting for your reply.','intel');if(!q.incoming&&q.answer!==null)add('intel',q.id+':reply','💬 Gift question answered','Open Gift Intelligence to read your reply.','intel')}}],['chaos',async()=>{const r=await sb.rpc('chaos_state',{fid});if(r.error)throw r.error;const d=r.data;if(!d.entries.some(x=>x.week===d.week&&x.user_id===uid))add('chaos',d.week,'🎲 Wildcard Wednesday','Your weekly challenge is waiting.','chaos')}],['battles',async()=>{for(const b of battles){if(!votes.some(v=>v.battle_id===b.id&&v.user_id===uid))add('battles',b.id,'⚔️ Gift Battle','A battle is available to vote on.','battle')}}]];
await Promise.all(jobs.map(async ([kind,fn])=>{if(!state.prefs[kind])return;try{await fn()}catch{errors.push(kind)}}));if(family?.id!==fid||user?.id!==uid||el!==$(el.id))return;entries.sort((a,b)=>a.kind.localeCompare(b.kind)||a.id.localeCompare(b.id));const unread=entries.filter(n=>!state.read.includes(n.id));const go=t=>{navigate(t)};
if(!full){el.innerHTML=card(`<div class="row"><h3>🔔 Notifications</h3><button id="openNotifications" class="secondary">${unread.length} unread · Open</button></div><p class="muted">${errors.length?'Some reminders could not be checked.':entries.length?'Your circle reminders are ready.':'You are all caught up.'}</p>`);$('openNotifications').onclick=()=>go('notifications');return}
const labels={celebrations:'Birthdays and celebrations',santa:'Secret Santa',intel:'Anonymous questions and replies',chaos:'Weekly challenges',battles:'Gift Battles'};el.innerHTML=card(`<div class="row"><h3>${unread.length} unread</h3><button id="notifReadAll" class="secondary">Mark all read</button></div>${errors.length?'<p class="muted">Could not check: '+esc(errors.join(', '))+'</p>':''}${entries.map((n,i)=>`<div class="item"><b>${state.read.includes(n.id)?'':'● '}${esc(n.title)}</b><p class="muted">${esc(n.detail)}</p><button data-notif-open="${i}">Open</button>${state.read.includes(n.id)?'':`<button class="secondary" data-notif-read="${i}">Mark read</button>`}</div>`).join('')||'<p>No current reminders.</p>'}`)+card(`<h3>⚙️ Reminder preferences</h3><p class="muted">Saved on this device, separately for each circle.</p>${Object.entries(labels).map(([k,v])=>`<label style="display:flex;align-items:center;gap:10px"><input type="checkbox" style="width:auto" data-notif-pref="${k}" ${state.prefs[k]?'checked':''}>${v}</label>`).join('')}<button id="notifRefresh" class="secondary">Refresh reminders</button><p class="muted">In-app only. No lock-screen or background push notifications.</p>`);function persist(){if(!saveNotificationState(state))msg('Could not save reminder preferences on this device.');}function read(n){state.read=[...new Set([...state.read,n.id])].slice(-1000);persist()}$('notifReadAll').onclick=()=>{state.read=[...new Set([...state.read,...entries.map(n=>n.id)])].slice(-1000);persist();loadNotifications()};el.querySelectorAll('[data-notif-open]').forEach(b=>b.onclick=()=>{const n=entries[Number(b.dataset.notifOpen)];read(n);go(n.dest)});el.querySelectorAll('[data-notif-read]').forEach(b=>b.onclick=()=>{read(entries[Number(b.dataset.notifRead)]);loadNotifications()});el.querySelectorAll('[data-notif-pref]').forEach(b=>b.onchange=()=>{state.prefs[b.dataset.notifPref]=b.checked;persist();loadNotifications()});$('notifRefresh').onclick=()=>loadNotifications();}

// Arcade games are device-local, scoped to the signed-in member and circle.
const arcadeQuiz=[['Which planet has the shortest year?',['Mars','Mercury','Venus'],1],['How many sides does a hexagon have?',['Six','Eight','Five'],0],['Which instrument typically has 88 keys?',['Violin','Trumpet','Piano'],2],['Which ocean is largest?',['Atlantic','Pacific','Indian'],1],['What is the largest mammal?',['Blue whale','Elephant','Giraffe'],0],['Which country originated origami?',['Brazil','Japan','Italy'],1],['How many players start on a baseball field for the fielding team?',['Seven','Ten','Nine'],2],['What is the chemical symbol for gold?',['Au','Ag','Fe'],0],['Which animal has three hearts?',['Dolphin','Octopus','Penguin'],1],['Which planet is known as the Red Planet?',['Jupiter','Saturn','Mars'],2],['What is the smallest prime number?',['Two','One','Three'],0],['Which continent contains the Sahara?',['Asia','Africa','Australia'],1]];
function arcadeKey(){return 'gift-arcade:'+user.id+':'+family.id}
function arcadeScores(){try{return JSON.parse(localStorage.getItem(arcadeKey())||'{}')||{}}catch{return {}}}
function arcadeSave(game,score){try{const s=arcadeScores();s[game]=Math.max(Number(s[game])||0,score);localStorage.setItem(arcadeKey(),JSON.stringify(s));return true}catch{return false}}
function viewArcade(){const s=arcadeScores();return `<section class="hero"><small>FAMILY ARCADE</small><h2>🕹️ Game on!</h2><p>Quick games, personal bests and family challenges.</p></section>${card('<h3>Play together</h3><button data-tab="arcadeDaily">🏆 Daily trivia challenge</button><div id="competition">Loading family rankings…</div><button data-tab="chaos">🎲 Wildcard Wednesday & leaderboard</button><button data-tab="battle">⚔️ Gift Battles</button>')}${card(`<h3>Solo mini-games</h3><p class="muted">Personal bests on this device</p><button data-tab="arcadeQuiz">🧠 Trivia Sprint · Best ${Number(s.quiz)||0}/5</button><button data-tab="arcadeMemory">🃏 Memory Match · Best ${Number(s.memory)||0} points</button><button data-tab="arcadeGuess">🎯 Number Hunt · Best ${Number(s.guess)||0} points</button>`)} `}
function arcadeGame(title,body){return `<h2>${title}</h2>${card(body)}<button data-tab="arcade" class="secondary">Return to Arcade</button>`}
function viewArcadeGame(){return arcadeGame(tab==='arcadeQuiz'?'🧠 Trivia Sprint':tab==='arcadeMemory'?'🃏 Memory Match':'🎯 Number Hunt','<div id="arcadeGame"></div>')}
function shuffled(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function wireArcade(){const el=$('arcadeGame');if(!el)return;const game=tab;const active=()=>el===$('arcadeGame')&&tab===game;const finish=(key,score,detail)=>{if(!active())return;const saved=arcadeSave(key,score);el.innerHTML=`<h3>Round complete!</h3><p>${esc(detail)}</p><p>${saved?'Personal best saved on this device.':'Storage unavailable; score not saved.'}</p><p id="sharedScore" role="status">Saving shared score…</p><button id="arcadeReplay">Play again</button>`;const result=$("sharedScore");submitArcade(key,score,result);$('arcadeReplay').onclick=wireArcade};if(game==='arcadeQuiz'){let q=shuffled(arcadeQuiz).slice(0,5),i=0,score=0;const draw=()=>{if(!active())return;if(i===q.length){finish('quiz',score,`${score} / 5 correct`);return}const [question,options,correct]=q[i];el.innerHTML=`<p>Question ${i+1} of 5 · Score ${score}</p><h3>${esc(question)}</h3>${options.map((o,j)=>`<button data-answer="${j}">${esc(o)}</button>`).join('')}<p id="arcadeFeedback" role="status"></p>`;el.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{el.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);const yes=Number(b.dataset.answer)===correct;if(yes)score++;$('arcadeFeedback').textContent=yes?'Correct!':'Correct answer: '+options[correct];const next=document.createElement('button');next.textContent='Continue';next.onclick=()=>{i++;draw()};el.append(next)})};draw()}else if(game==='arcadeMemory'){const deck=shuffled(['🎁','🎁','🎄','🎄','🦄','🦄','🍕','🍕','🎮','🎮','⭐','⭐']);let open=[],matched=new Set(),moves=0,locked=false;const draw=()=>{if(!active())return;el.innerHTML=`<p>Pairs ${matched.size/2}/6 · Moves ${moves}</p><div class="arcade-grid">${deck.map((v,i)=>`<button data-tile="${i}" aria-label="${matched.has(i)||open.includes(i)?v:'Hidden tile '+(i+1)}" ${matched.has(i)||open.includes(i)||locked?'disabled':''}>${matched.has(i)||open.includes(i)?v:'?'}</button>`).join('')}</div>`;el.querySelectorAll('[data-tile]').forEach(b=>b.onclick=()=>{if(locked)return;open.push(Number(b.dataset.tile));if(open.length===2){moves++;if(deck[open[0]]===deck[open[1]]){open.forEach(x=>matched.add(x));open=[];if(matched.size===12){finish('memory',Math.max(1,100-(moves-6)*5),`${moves} moves to find all six pairs`);return}}else{locked=true;setTimeout(()=>{open=[];locked=false;draw()},850)}}draw()})};draw()}else{const target=1+Math.floor(Math.random()*100);let tries=0;el.innerHTML='<h3>Find the number from 1 to 100</h3><form id="arcadeGuessForm"><label>Guess<input id="arcadeNumber" type="number" min="1" max="100" step="1" required></label><button>Guess</button></form><p id="arcadeFeedback" role="status">You have 7 guesses.</p>';$('arcadeGuessForm').onsubmit=e=>{e.preventDefault();const n=Number($("arcadeNumber").value);if(!Number.isInteger(n)||n<1||n>100)return;tries++;if(n===target){finish('guess',80-tries*10,`Found it in ${tries} guesses!`);return}if(tries===7){finish('guess',0,`The number was ${target}.`);return}$('arcadeFeedback').textContent=`${n<target?'Higher':'Lower'}! ${7-tries} guesses left.`;$("arcadeNumber").value='';$("arcadeNumber").focus()}}}

// V16: shared casual scores and server-scored daily trivia.
async function submitArcade(game,score,el){const fid=family.id;try{const {error}=await sb.rpc('arcade_record',{fid,game_key:game,points:score});if(error)throw error;el.textContent='Shared score saved.'}catch(e){el.textContent='Shared score not saved: '+(e.message||e)}}
async function loadCompetition(){const el=$('competition');if(!el)return;const fid=family.id;try{const {data,error}=await sb.rpc('arcade_rankings',{fid});if(error)throw error;if(el!==$('competition')||family?.id!==fid)return;const rows=data||[];const board=(title,key)=>`<h4>${title}</h4>${rows.length?[...rows].sort((a,b)=>b[key]-a[key]||String(a.user_id).localeCompare(String(b.user_id))).map(r=>`<p>${esc(name(r.user_id))} · ${Number(r[key])} XP ${r[key]>=100?'🏅':''}</p>`).join(''):'<p class="muted">No scores yet.</p>'}`;el.innerHTML=board('Weekly championship','weekly_xp')+board('All-time championship','total_xp')+'<h4>Shared personal records</h4>'+rows.map(r=>`<p>${esc(name(r.user_id))} · Trivia ${Number(r.quiz)}/5 · Memory ${Number(r.memory)} · Number ${Number(r.guess)}</p>`).join('')+'<p class="muted">Daily trivia earns 10 competition XP per correct answer. Casual games are honor-system scores.</p>'}catch(e){el.textContent='Rankings unavailable: '+(e.message||e)}}
async function wireDaily(){const el=$('dailyGame');if(!el)return;const fid=family.id,active=()=>el===$('dailyGame')&&family?.id===fid;el.textContent='Loading today’s challenge…';try{const {data,error}=await sb.rpc('arcade_daily',{fid});if(error)throw error;if(!active())return;if(data.score!==null){el.textContent=`Already completed today: ${data.score}/5 correct. Come back tomorrow (UTC).`;return}const questions=data.questions,answers=[];let i=0;const draw=()=>{if(!active())return;const q=questions[i];el.innerHTML=`<p>${i+1} / 5</p><h3>${esc(q.question)}</h3>${q.options.map((o,j)=>`<button data-daily="${j}">${esc(o)}</button>`).join('')}`;el.querySelectorAll('[data-daily]').forEach(b=>b.onclick=async()=>{el.querySelectorAll('button').forEach(x=>x.disabled=true);answers.push(Number(b.dataset.daily));i++;if(i<questions.length){draw();return}el.textContent='Submitting…';try{const r=await sb.rpc('arcade_daily_submit',{fid,challenge_day:data.day,answers});if(r.error)throw r.error;if(active())el.textContent=`Daily challenge complete: ${r.data}/5 correct. ${r.data*10} competition XP!`}catch(e){if(active())el.textContent='Submission unavailable: '+(e.message||e)}})};draw()}catch(e){if(active())el.textContent='Challenge unavailable: '+(e.message||e)}}
